let coastal=false;export function setCoastal(value){coastal=value}
function onBeach(x,z,margin){return coastal&&x>=-47+margin&&x<=-24&&z>=-82+margin&&z<=52-margin}
// Shared road geometry and routing. The player, pedestrians and rivals use the same map.
export const VERTICAL=[-24,0,24], HORIZONTAL=[-64,-38,-12,14,40], ROAD_HALF=4.2;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function onRoad(x,z,margin=.55){const r=ROAD_HALF-margin;return onBeach(x,z,margin)||inField(x,z,margin)||(z>=-83+margin&&z<=53-margin&&VERTICAL.some(v=>Math.abs(x-v)<=r))||(x>=-31+margin&&x<=31-margin&&HORIZONTAL.some(v=>Math.abs(z-v)<=r));}
export function inField(x,z,margin=.6){return (x>=4+margin&&x<=20-margin&&z>=-59+margin&&z<=-44-margin)||(x>=0&&x<=24&&z>=-54+margin&&z<=-48-margin)}
export function nearestRoad(x,z,margin=.65){const r=ROAD_HALF-margin,candidates=[...(coastal?[{x:clamp(x,-47+margin,-24),z:clamp(z,-82+margin,52-margin)}]:[]),{x:clamp(x,4+margin,20-margin),z:clamp(z,-59+margin,-44-margin)},{x:clamp(x,0,24),z:clamp(z,-54+margin,-48-margin)},...VERTICAL.map(v=>({x:clamp(x,v-r,v+r),z:clamp(z,-83+margin,53-margin)})),...HORIZONTAL.map(v=>({x:clamp(x,-31+margin,31-margin),z:clamp(z,v-r,v+r)}))];return candidates.sort((a,b)=>(a.x-x)**2+(a.z-z)**2-((b.x-x)**2+(b.z-z)**2))[0];}
export function moveOnRoad(position,dx,dz,margin=.65){const steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.2));for(let i=0;i<steps;i++){const x=position.x+dx/steps,z=position.z+dz/steps;if(onRoad(x,z,margin)){position.x=x;position.z=z}else{if(onRoad(x,position.z,margin))position.x=x;if(onRoad(position.x,z,margin))position.z=z}}}
export function clearRoute(a,b){const n=Math.ceil(Math.hypot(a.x-b.x,a.z-b.z)/.4);for(let i=0;i<=n;i++){const t=n?i/n:0;if(!onRoad(a.x+(b.x-a.x)*t,a.z+(b.z-a.z)*t,1.2))return false}return true;}
export function routeBetween(from,to){const end=nearestRoad(to.x,to.z,1.2),start=nearestRoad(from.x,from.z,1.2);if(clearRoute(start,end))return[end];const nodes=[start,end,...(coastal?HORIZONTAL.map(z=>({x:-39,z})):[]),{x:0,z:-51},{x:12,z:-51},{x:24,z:-51},...VERTICAL.flatMap(x=>HORIZONTAL.map(z=>({x,z})))],dist=nodes.map(()=>Infinity),previous=nodes.map(()=>-1),visited=new Set();dist[0]=0;for(let n=0;n<nodes.length;n++){let a=-1;nodes.forEach((_,i)=>{if(!visited.has(i)&&(a<0||dist[i]<dist[a]))a=i});if(a<0||!Number.isFinite(dist[a]))break;if(a===1)break;visited.add(a);nodes.forEach((b,j)=>{if(j===a||visited.has(j)||!clearRoute(nodes[a],b))return;const d=dist[a]+Math.hypot(nodes[a].x-b.x,nodes[a].z-b.z);if(d<dist[j]){dist[j]=d;previous[j]=a}})}if(previous[1]<0)return[start];const path=[];for(let at=1;at!==0;at=previous[at])path.unshift(nodes[at]);return path;}
export function streetName(x,z){if(inField(x,z))return 'Community Field';if(Math.abs(z+64)<4.2)return 'Cedar Street';if(Math.abs(z+38)<4.2)return 'Field Road';if(Math.abs(z-40)<4.2)return 'School Lane';if(Math.abs(z+12)<4.2)return 'Market Street';if(Math.abs(z-14)<4.2)return 'Protea Lane';return x<-12?'Taxi Rank Road':x>12?'Mountain View Road':'Spaza Street';}

